import java.util.*;
public class SeparateChainingHashTable { ArrayList<ArrayList<String>> table=new ArrayList<ArrayList<String>>(); public SeparateChainingHashTable(){for(int i=0;i<5;i++)table.add(new ArrayList<String>());} int hash(String s){int h=0;for(int i=0;i<s.length();i++)h=(31*h+s.charAt(i))%table.size();return h;} void add(String s){table.get(hash(s)).add(s);} boolean contains(String s){return table.get(hash(s)).contains(s);} public static void run(){SeparateChainingHashTable h=new SeparateChainingHashTable();for(String s:new String[]{"tree","heap","hash","graph"})h.add(s);System.out.println("Separate chaining table="+h.table+", contains heap="+h.contains("heap"));System.out.println("Invariant: each bucket stores keys with the same table index; expected O(1) with bounded load.\n");} public static void main(String[] args){run();}}
